create table public.sentence (
 id text primary key,
 text_ja text not null check(length(btrim(text_ja))>0),
 translation_ko text not null check(length(btrim(translation_ko))>0),
 status text not null default 'draft' check(status in ('draft','published','inactive')),
 batch text not null,
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now()
);
create table public.sentence_socket (
 id uuid primary key default gen_random_uuid(),
 sentence_id text not null references public.sentence(id) on delete cascade,
 start_offset integer not null check(start_offset>=0),
 end_offset integer not null,
 original_text text not null check(length(original_text)>0),
 check(end_offset>start_offset),
 unique(sentence_id,start_offset,end_offset)
);
comment on column public.sentence_socket.start_offset is 'UTF-16 code units; zero-based inclusive. Revalidate sockets when editing the sentence.';
comment on column public.sentence_socket.end_offset is 'UTF-16 code units; exclusive.';
create table public.sentence_option (
 id uuid primary key default gen_random_uuid(),
 socket_id uuid not null references public.sentence_socket(id) on delete cascade,
 word_id uuid references public.word(id) on delete restrict,
 display_text text not null check(length(btrim(display_text))>0),
 reading text,
 is_accepted boolean not null,
 unique(socket_id,display_text)
);
create index sentence_option_word_idx on public.sentence_option(word_id) where word_id is not null;
alter table public.sentence enable row level security;
alter table public.sentence_socket enable row level security;
alter table public.sentence_option enable row level security;
revoke all on public.sentence,public.sentence_socket,public.sentence_option from anon,authenticated;
grant select on public.sentence,public.sentence_socket,public.sentence_option to authenticated;
grant all on public.sentence,public.sentence_socket,public.sentence_option to service_role;
create policy sentence_published_read on public.sentence for select to authenticated using(status='published');
create policy socket_published_read on public.sentence_socket for select to authenticated using(exists(select 1 from public.sentence s where s.id=sentence_id and s.status='published'));
create policy option_published_read on public.sentence_option for select to authenticated using(exists(select 1 from public.sentence_socket sk join public.sentence s on s.id=sk.sentence_id where sk.id=socket_id and s.status='published'));

-- The JSON pilot was generated by this change and has never been user-editable.
-- Refuse to remove unexpected data instead of silently discarding it.
do $$ begin
 if exists(select 1 from public.reading_sentence where batch<>'sentence-pilot-100-v1') then
 raise exception 'Unexpected legacy sentence content'; end if;
end $$;

create temporary table sentence_import(data jsonb) on commit drop;
insert into sentence_import values ($bank$[{"id":"reading-v1-001","text":"資料の日付を確認しました。古い版だったので担当者に連絡しました。","translation":"자료의 날짜를 확인했습니다. 구판이어서 담당자에게 알렸습니다.","sockets":[{"original":"確認しました","start":6,"options":[{"text":"確認しました","accepted":true},{"text":"チェックしました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"連絡しました","start":25,"options":[{"text":"連絡しました","accepted":true},{"text":"知らせました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-002","text":"会議の前に、参加者に資料を送ります。","translation":"회의 전에 참가자에게 자료를 보냅니다.","sockets":[{"original":"前に","start":3,"options":[{"text":"前に","accepted":true},{"text":"前もって","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"送ります","start":13,"options":[{"text":"送ります","accepted":true},{"text":"送付します","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-003","text":"費用を見積もってから、契約の内容を確認します。","translation":"비용을 견적 낸 뒤 계약 내용을 확인합니다.","sockets":[{"original":"見積もって","start":3,"options":[{"text":"見積もって","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"確認します","start":17,"options":[{"text":"確認します","accepted":true},{"text":"チェックします","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-004","text":"設備の設計について、来週の会議で説明します。","translation":"설비 설계에 관해 다음 주 회의에서 설명합니다.","sockets":[{"original":"設計","start":3,"options":[{"text":"設計","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"説明します","start":16,"options":[{"text":"説明します","accepted":true},{"text":"解説します","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-005","text":"部品を調達してから、製品を組み立てます。","translation":"부품을 조달한 뒤 제품을 조립합니다.","sockets":[{"original":"調達して","start":3,"options":[{"text":"調達して","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"組み立てます","start":13,"options":[{"text":"組み立てます","accepted":true},{"text":"組み上げます","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-006","text":"担当者が不在のため、回答は明日までお待ちください。お急ぎの場合は受付にご相談ください。","translation":"담당자가 부재중이므로 답변은 내일까지 기다려 주세요. 급하시면 접수처에 상담해 주세요.","sockets":[{"original":"お待ちください","start":17,"options":[{"text":"お待ちください","accepted":true},{"text":"待ってください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"ご相談ください","start":35,"options":[{"text":"ご相談ください","accepted":true},{"text":"相談してください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-007","text":"氏名と日付を忘れずに記入してください。","translation":"이름과 날짜를 빠짐없이 적어 주세요.","sockets":[{"original":"日付","start":3,"options":[{"text":"日付","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"記入してください","start":10,"options":[{"text":"記入してください","accepted":true},{"text":"書いてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-008","text":"添付資料を開いて、最初のページを確認してください。","translation":"첨부 자료를 열어 첫 페이지를 확인해 주세요.","sockets":[{"original":"開いて","start":5,"options":[{"text":"開いて","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"確認してください","start":16,"options":[{"text":"確認してください","accepted":true},{"text":"チェックしてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-009","text":"計画の趣旨が伝わるように、詳しく説明しました。","translation":"계획의 취지가 전달되도록 자세히 설명했습니다.","sockets":[{"original":"趣旨","start":3,"options":[{"text":"趣旨","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"説明しました","start":16,"options":[{"text":"説明しました","accepted":true},{"text":"解説しました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-010","text":"数値に誤りがあったため、すぐに修正しました。","translation":"수치에 오류가 있어서 즉시 수정했습니다.","sockets":[{"original":"誤り","start":3,"options":[{"text":"誤り","accepted":true},{"text":"間違い","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"修正しました","start":15,"options":[{"text":"修正しました","accepted":true},{"text":"訂正しました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-011","text":"手順が変わったので、新しい資料を配りました。変更点も説明しました。","translation":"절차가 바뀌어서 새 자료를 배포했습니다. 변경점도 설명했습니다.","sockets":[{"original":"配りました","start":16,"options":[{"text":"配りました","accepted":true},{"text":"配布しました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"説明しました","start":26,"options":[{"text":"説明しました","accepted":true},{"text":"解説しました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-012","text":"重複している部分を削除しました。","translation":"중복된 부분을 삭제했습니다.","sockets":[{"original":"重複","start":0,"options":[{"text":"重複","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"削除しました","start":9,"options":[{"text":"削除しました","accepted":true},{"text":"消しました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-013","text":"説明だけでは難しいので、具体的な例を示して解説します。","translation":"설명만으로는 어려워서 구체적인 예를 들어 설명합니다.","sockets":[{"original":"示して","start":18,"options":[{"text":"示して","accepted":true},{"text":"挙げて","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"解説します","start":21,"options":[{"text":"解説します","accepted":true},{"text":"説明します","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-014","text":"連絡先が変わったら、登録情報を修正して、担当者に知らせてください。","translation":"연락처가 바뀌면 등록 정보를 수정하고 담당자에게 알려 주세요.","sockets":[{"original":"修正して","start":15,"options":[{"text":"修正して","accepted":true},{"text":"訂正して","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"知らせてください","start":24,"options":[{"text":"知らせてください","accepted":true},{"text":"連絡してください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-015","text":"会議の後で資料を整理して、棚に戻してください。","translation":"회의 뒤에 자료를 정리해서 선반에 돌려놓아 주세요.","sockets":[{"original":"整理して","start":8,"options":[{"text":"整理して","accepted":true},{"text":"片付けて","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"戻してください","start":15,"options":[{"text":"戻してください","accepted":true},{"text":"返してください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-016","text":"締め切りが近いので、書類を早めに送ってください。","translation":"마감이 가까우므로 서류를 일찍 보내 주세요.","sockets":[{"original":"早めに","start":13,"options":[{"text":"早めに","accepted":true},{"text":"早いうちに","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"送ってください","start":16,"options":[{"text":"送ってください","accepted":true},{"text":"送付してください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-017","text":"電話がつながらなかったので、メールで連絡しました。返信を待っています。","translation":"전화가 연결되지 않아서 이메일로 알렸습니다. 답장을 기다리고 있습니다.","sockets":[{"original":"連絡しました","start":18,"options":[{"text":"連絡しました","accepted":true},{"text":"知らせました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"待っています","start":28,"options":[{"text":"待っています","accepted":true},{"text":"待っているところです","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-018","text":"申請書を出す前に、内容を確認して、間違いを修正してください。","translation":"신청서를 내기 전에 내용을 확인하고 틀린 곳을 수정해 주세요.","sockets":[{"original":"確認して","start":12,"options":[{"text":"確認して","accepted":true},{"text":"チェックして","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"修正してください","start":21,"options":[{"text":"修正してください","accepted":true},{"text":"訂正してください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-019","text":"新しい日程を添付しましたので、ご確認ください。","translation":"새 일정을 첨부했으니 확인해 주세요.","sockets":[{"original":"添付しました","start":6,"options":[{"text":"添付しました","accepted":true},{"text":"添付してあります","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"ご確認ください","start":15,"options":[{"text":"ご確認ください","accepted":true},{"text":"確認してください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-020","text":"会議室を使った後は照明を消して、窓を閉めてください。","translation":"회의실을 사용한 뒤에는 조명을 끄고 창문을 닫아 주세요.","sockets":[{"original":"消して","start":12,"options":[{"text":"消して","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"閉めてください","start":18,"options":[{"text":"閉めてください","accepted":true},{"text":"閉じてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-021","text":"製品に問題があれば、購入した店に連絡して、対応を相談してください。","translation":"제품에 문제가 있으면 구입한 가게에 연락하고 대응을 상담해 주세요.","sockets":[{"original":"連絡して","start":16,"options":[{"text":"連絡して","accepted":true},{"text":"知らせて","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"相談してください","start":24,"options":[{"text":"相談してください","accepted":true},{"text":"相談してみてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-022","text":"資料の作り方は前回の例を参考にしてください。不明点は担当者に聞いてください。","translation":"자료 만드는 법은 지난번 예를 참고해 주세요. 모르는 점은 담당자에게 물어보세요.","sockets":[{"original":"参考にしてください","start":12,"options":[{"text":"参考にしてください","accepted":true},{"text":"参考にしてみてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"聞いてください","start":30,"options":[{"text":"聞いてください","accepted":true},{"text":"尋ねてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-023","text":"送料を含む合計金額を確認してから、支払ってください。","translation":"배송비를 포함한 합계 금액을 확인한 뒤 지불해 주세요.","sockets":[{"original":"確認して","start":10,"options":[{"text":"確認して","accepted":true},{"text":"チェックして","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"支払ってください","start":17,"options":[{"text":"支払ってください","accepted":true},{"text":"お支払いください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-024","text":"欠席する場合は、できるだけ早く主催者に知らせてください。","translation":"결석할 때는 가능한 한 빨리 주최자에게 알려 주세요.","sockets":[{"original":"早く","start":13,"options":[{"text":"早く","accepted":true},{"text":"速やかに","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"知らせてください","start":19,"options":[{"text":"知らせてください","accepted":true},{"text":"連絡してください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-025","text":"作業の記録を残して、共有フォルダーに保存します。","translation":"작업 기록을 남겨 공유 폴더에 저장합니다.","sockets":[{"original":"残して","start":6,"options":[{"text":"残して","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"保存します","start":18,"options":[{"text":"保存します","accepted":true},{"text":"保存しておきます","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-026","text":"雨で道が滑りやすいので、足元に注意して、ゆっくり歩いてください。","translation":"비 때문에 길이 미끄러우니 발밑을 조심하며 천천히 걸어 주세요.","sockets":[{"original":"注意して","start":15,"options":[{"text":"注意して","accepted":true},{"text":"気を付けて","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"歩いてください","start":24,"options":[{"text":"歩いてください","accepted":true},{"text":"歩きましょう","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-027","text":"ぬれた床を走ると転びます。移動の際は注意してください。","translation":"젖은 바닥을 달리면 넘어집니다. 이동할 때는 조심해 주세요.","sockets":[{"original":"転びます","start":8,"options":[{"text":"転びます","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"注意してください","start":18,"options":[{"text":"注意してください","accepted":true},{"text":"気を付けてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-028","text":"作業の前に手を洗って、清潔な手袋を着けてください。","translation":"작업 전에 손을 씻고 깨끗한 장갑을 착용해 주세요.","sockets":[{"original":"洗って","start":7,"options":[{"text":"洗って","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"着けてください","start":17,"options":[{"text":"着けてください","accepted":true},{"text":"着用してください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-029","text":"熱と咳があるため、今日は家で休みます。","translation":"열과 기침이 있어서 오늘은 집에서 쉽니다.","sockets":[{"original":"咳","start":2,"options":[{"text":"咳","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"休みます","start":14,"options":[{"text":"休みます","accepted":true},{"text":"休養します","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-030","text":"体調が悪いときは上司に連絡して、無理をせず休んでください。","translation":"몸이 좋지 않을 때는 상사에게 알리고 무리하지 말고 쉬어 주세요.","sockets":[{"original":"連絡して","start":11,"options":[{"text":"連絡して","accepted":true},{"text":"知らせて","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"休んでください","start":21,"options":[{"text":"休んでください","accepted":true},{"text":"休養してください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-031","text":"異常な音がしたため、機械を止めて、原因を調べました。","translation":"이상한 소리가 나서 기계를 멈추고 원인을 조사했습니다.","sockets":[{"original":"止めて","start":13,"options":[{"text":"止めて","accepted":true},{"text":"停止して","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"調べました","start":20,"options":[{"text":"調べました","accepted":true},{"text":"調査しました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-032","text":"火災の際は階段から避難してください。係員の指示を守ってください。","translation":"화재 시에는 계단으로 대피해 주세요. 담당자의 지시를 지켜 주세요.","sockets":[{"original":"避難してください","start":9,"options":[{"text":"避難してください","accepted":true},{"text":"逃げてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"守ってください","start":24,"options":[{"text":"守ってください","accepted":true},{"text":"守りましょう","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-033","text":"重い荷物は一人で持たず、近くの人に声をかけて、手伝いを頼んでください。","translation":"무거운 짐은 혼자 들지 말고 가까운 사람에게 말을 걸어 도움을 부탁해 주세요.","sockets":[{"original":"声をかけて","start":17,"options":[{"text":"声をかけて","accepted":true},{"text":"呼びかけて","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"頼んでください","start":27,"options":[{"text":"頼んでください","accepted":true},{"text":"お願いしてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-034","text":"通路の箱を別の場所に移しました。その後、通れるか確認しました。","translation":"통로의 상자를 다른 곳으로 옮겼습니다. 그 뒤 통행할 수 있는지 확인했습니다.","sockets":[{"original":"移しました","start":10,"options":[{"text":"移しました","accepted":true},{"text":"移動しました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"確認しました","start":24,"options":[{"text":"確認しました","accepted":true},{"text":"チェックしました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-035","text":"機械に触れる前に電源を切って、停止したことを確認してください。","translation":"기계에 손대기 전에 전원을 끄고 정지했는지 확인해 주세요.","sockets":[{"original":"切って","start":11,"options":[{"text":"切って","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"確認してください","start":22,"options":[{"text":"確認してください","accepted":true},{"text":"チェックしてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-036","text":"暑い日には水分をこまめに取って、体調に気を付けてください。","translation":"더운 날에는 수분을 자주 보충하고 건강에 주의해 주세요.","sockets":[{"original":"取って","start":12,"options":[{"text":"取って","accepted":true},{"text":"補給して","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"気を付けてください","start":19,"options":[{"text":"気を付けてください","accepted":true},{"text":"注意してください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-037","text":"薬を飲む前に、説明書の内容を確認してください。","translation":"약을 먹기 전에 설명서 내용을 확인해 주세요.","sockets":[{"original":"前に","start":4,"options":[{"text":"前に","accepted":true},{"text":"前もって","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"確認してください","start":14,"options":[{"text":"確認してください","accepted":true},{"text":"チェックしてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-038","text":"落ちた部品を拾って、決められた箱に入れてください。","translation":"떨어진 부품을 주워 정해진 상자에 넣어 주세요.","sockets":[{"original":"拾って","start":6,"options":[{"text":"拾って","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"入れてください","start":17,"options":[{"text":"入れてください","accepted":true},{"text":"入れておいてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-039","text":"勤務中の飲酒は禁止です。規則を守ってください。","translation":"근무 중 음주는 금지입니다. 규칙을 지켜 주세요.","sockets":[{"original":"飲酒","start":4,"options":[{"text":"飲酒","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"守ってください","start":15,"options":[{"text":"守ってください","accepted":true},{"text":"守りましょう","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-040","text":"非常口の前には物を置かないでください。通れる状態を保ってください。","translation":"비상구 앞에는 물건을 놓지 마세요. 통행 가능한 상태를 유지해 주세요.","sockets":[{"original":"置かないでください","start":9,"options":[{"text":"置かないでください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"保ってください","start":25,"options":[{"text":"保ってください","accepted":true},{"text":"維持してください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-041","text":"電車は九時に発車します。余裕を持って駅に来てください。","translation":"전철은 9시에 출발합니다. 여유를 두고 역으로 와 주세요.","sockets":[{"original":"発車します","start":6,"options":[{"text":"発車します","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"来てください","start":20,"options":[{"text":"来てください","accepted":true},{"text":"お越しください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-042","text":"乗り換えの前にホームの位置を確認して、準備しておきます。","translation":"환승 전에 승강장 위치를 확인하고 준비해 둡니다.","sockets":[{"original":"確認して","start":14,"options":[{"text":"確認して","accepted":true},{"text":"チェックして","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"おきます","start":23,"options":[{"text":"おきます","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]}]},{"id":"reading-v1-043","text":"出張の日程が決まったので、宿泊する旅館を予約します。","translation":"출장 일정이 정해져서 숙박할 여관을 예약합니다.","sockets":[{"original":"旅館","start":17,"options":[{"text":"旅館","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"予約します","start":20,"options":[{"text":"予約します","accepted":true},{"text":"予約しておきます","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-044","text":"渋滞で到着が遅れると先方に連絡しました。約束の時間も変更しました。","translation":"교통 체증으로 도착이 늦어진다고 상대방에게 알렸습니다. 약속 시간도 변경했습니다.","sockets":[{"original":"連絡しました","start":13,"options":[{"text":"連絡しました","accepted":true},{"text":"知らせました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"変更しました","start":26,"options":[{"text":"変更しました","accepted":true},{"text":"変えました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-045","text":"駅からの道を調べて、地図を保存しました。","translation":"역에서 가는 길을 확인하고 지도를 저장했습니다.","sockets":[{"original":"調べて","start":6,"options":[{"text":"調べて","accepted":true},{"text":"確認して","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"保存しました","start":13,"options":[{"text":"保存しました","accepted":true},{"text":"保存しておきました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-046","text":"入口が分からなければ係員に尋ねてください。案内板も確認してください。","translation":"입구를 모르겠으면 담당자에게 물어보세요. 안내판도 확인해 주세요.","sockets":[{"original":"尋ねてください","start":13,"options":[{"text":"尋ねてください","accepted":true},{"text":"聞いてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"確認してください","start":25,"options":[{"text":"確認してください","accepted":true},{"text":"チェックしてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-047","text":"電車が止まったので、別の交通手段を調べています。分かり次第知らせます。","translation":"전철이 멈춰 다른 교통수단을 알아보고 있습니다. 알아내는 대로 알리겠습니다.","sockets":[{"original":"調べています","start":17,"options":[{"text":"調べています","accepted":true},{"text":"調べているところです","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"知らせます","start":29,"options":[{"text":"知らせます","accepted":true},{"text":"連絡します","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-048","text":"宿泊費とは別に食事の料金がかかります。合計を確認してください。","translation":"숙박비와 별도로 식사 요금이 듭니다. 합계를 확인해 주세요.","sockets":[{"original":"料金","start":10,"options":[{"text":"料金","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"確認してください","start":22,"options":[{"text":"確認してください","accepted":true},{"text":"チェックしてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-049","text":"忘れ物について駅員に相談しました。荷物の特徴を説明しました。","translation":"분실물에 관해 역무원과 상담했습니다. 짐의 특징을 설명했습니다.","sockets":[{"original":"相談しました","start":10,"options":[{"text":"相談しました","accepted":true},{"text":"相談してみました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"説明しました","start":23,"options":[{"text":"説明しました","accepted":true},{"text":"伝えました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-050","text":"飛行機が遅れています。最新情報を確認して、ここでお待ちください。","translation":"비행기가 지연되고 있습니다. 최신 정보를 확인하고 여기서 기다려 주세요.","sockets":[{"original":"確認して","start":16,"options":[{"text":"確認して","accepted":true},{"text":"チェックして","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"お待ちください","start":24,"options":[{"text":"お待ちください","accepted":true},{"text":"待ってください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-051","text":"商品が届いたら数量を確認してください。不足があれば知らせてください。","translation":"상품이 도착하면 수량을 확인해 주세요. 부족하면 알려 주세요.","sockets":[{"original":"確認してください","start":10,"options":[{"text":"確認してください","accepted":true},{"text":"チェックしてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"知らせてください","start":25,"options":[{"text":"知らせてください","accepted":true},{"text":"連絡してください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-052","text":"この製品は日本製です。詳しい仕様は説明書で確認できます。","translation":"이 제품은 일본제입니다. 자세한 사양은 설명서에서 확인할 수 있습니다.","sockets":[{"original":"製","start":7,"options":[{"text":"製","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"確認できます","start":21,"options":[{"text":"確認できます","accepted":true},{"text":"チェックできます","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-053","text":"価格が変わったので、店頭の表示を修正しました。古い表示は外しました。","translation":"가격이 바뀌어서 매장 표시를 수정했습니다. 옛 표시는 떼어 냈습니다.","sockets":[{"original":"修正しました","start":16,"options":[{"text":"修正しました","accepted":true},{"text":"訂正しました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"外しました","start":28,"options":[{"text":"外しました","accepted":true},{"text":"取り外しました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-054","text":"組み立てる前に部品を確認してください。不足があれば担当者に知らせてください。","translation":"조립 전에 부품을 확인해 주세요. 부족하면 담당자에게 알려 주세요.","sockets":[{"original":"確認してください","start":10,"options":[{"text":"確認してください","accepted":true},{"text":"チェックしてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"知らせてください","start":29,"options":[{"text":"知らせてください","accepted":true},{"text":"連絡してください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-055","text":"特売の商品は数が限られています。早めにお越しください。","translation":"특가 상품은 수량이 한정되어 있습니다. 일찍 와 주세요.","sockets":[{"original":"早めに","start":16,"options":[{"text":"早めに","accepted":true},{"text":"早いうちに","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"お越しください","start":19,"options":[{"text":"お越しください","accepted":true},{"text":"来てください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-056","text":"包装が破れていたので、中身を確認しました。状態を写真に撮りました。","translation":"포장이 찢어져 있어서 내용물을 확인했습니다. 상태를 사진으로 찍었습니다.","sockets":[{"original":"確認しました","start":14,"options":[{"text":"確認しました","accepted":true},{"text":"チェックしました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"撮りました","start":27,"options":[{"text":"撮りました","accepted":true},{"text":"撮影しました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-057","text":"届いたらすぐ冷蔵庫に入れてください。保管方法も確認してください。","translation":"도착하면 즉시 냉장고에 넣어 주세요. 보관 방법도 확인해 주세요.","sockets":[{"original":"入れてください","start":10,"options":[{"text":"入れてください","accepted":true},{"text":"入れておいてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"確認してください","start":23,"options":[{"text":"確認してください","accepted":true},{"text":"チェックしてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-058","text":"注文する前に色と価格を確認しましょう。不明な点は店員に尋ねましょう。","translation":"주문 전에 색상과 가격을 확인합시다. 모르는 점은 점원에게 물어봅시다.","sockets":[{"original":"確認しましょう","start":11,"options":[{"text":"確認しましょう","accepted":true},{"text":"チェックしましょう","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"尋ねましょう","start":27,"options":[{"text":"尋ねましょう","accepted":true},{"text":"聞きましょう","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-059","text":"入荷したらお客様に連絡します。それまでお待ちください。","translation":"입고되면 고객에게 알려 드리겠습니다. 그때까지 기다려 주세요.","sockets":[{"original":"連絡します","start":9,"options":[{"text":"連絡します","accepted":true},{"text":"知らせます","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"お待ちください","start":19,"options":[{"text":"お待ちください","accepted":true},{"text":"待ってください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-060","text":"返品にはレシートを用意して、商品と一緒にお持ちください。","translation":"반품하려면 영수증을 준비하고 상품과 함께 가져와 주세요.","sockets":[{"original":"用意して","start":9,"options":[{"text":"用意して","accepted":true},{"text":"準備して","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"お持ちください","start":20,"options":[{"text":"お持ちください","accepted":true},{"text":"持ってきてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-061","text":"領収書を添付して、申請書に金額を記入してください。","translation":"영수증을 첨부하고 신청서에 금액을 적어 주세요.","sockets":[{"original":"添付して","start":4,"options":[{"text":"添付して","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"記入してください","start":16,"options":[{"text":"記入してください","accepted":true},{"text":"書いてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-062","text":"予定外の出費が多かったため、予算を見直します。","translation":"예상 밖의 지출이 많아서 예산을 재검토합니다.","sockets":[{"original":"出費","start":4,"options":[{"text":"出費","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"見直します","start":17,"options":[{"text":"見直します","accepted":true},{"text":"再検討します","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-063","text":"送金する前に振込先を確認してください。誤りがあれば修正してください。","translation":"송금 전에 입금 계좌를 확인해 주세요. 오류가 있으면 수정해 주세요.","sockets":[{"original":"確認してください","start":10,"options":[{"text":"確認してください","accepted":true},{"text":"チェックしてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"修正してください","start":25,"options":[{"text":"修正してください","accepted":true},{"text":"訂正してください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-064","text":"受付で氏名を伝えてください。本人確認の書類も用意してください。","translation":"접수처에서 이름을 알려 주세요. 본인 확인 서류도 준비해 주세요.","sockets":[{"original":"伝えてください","start":6,"options":[{"text":"伝えてください","accepted":true},{"text":"知らせてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"用意してください","start":22,"options":[{"text":"用意してください","accepted":true},{"text":"準備してください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-065","text":"支払いの期限は今月の12日です。遅れないように注意してください。","translation":"납부 기한은 이번 달 12일입니다. 늦지 않도록 주의해 주세요.","sockets":[{"original":"12日","start":10,"options":[{"text":"12日","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"注意してください","start":23,"options":[{"text":"注意してください","accepted":true},{"text":"ご注意ください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-066","text":"署名する前に解約条件を確認しましょう。不明点は担当者に聞きましょう。","translation":"서명 전에 해지 조건을 확인합시다. 모르는 점은 담당자에게 물어봅시다.","sockets":[{"original":"確認しましょう","start":11,"options":[{"text":"確認しましょう","accepted":true},{"text":"チェックしましょう","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"聞きましょう","start":27,"options":[{"text":"聞きましょう","accepted":true},{"text":"尋ねましょう","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-067","text":"申請書が空欄だったので本人に連絡しました。情報を追加してもらいました。","translation":"신청서가 빈칸이어서 본인에게 알렸습니다. 정보를 추가해 받았습니다.","sockets":[{"original":"連絡しました","start":14,"options":[{"text":"連絡しました","accepted":true},{"text":"知らせました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"もらいました","start":28,"options":[{"text":"もらいました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]}]},{"id":"reading-v1-068","text":"キャンセル料について確認してください。分からなければ電話で相談してください。","translation":"취소 수수료에 관해 확인해 주세요. 모르겠으면 전화로 상담해 주세요.","sockets":[{"original":"確認してください","start":10,"options":[{"text":"確認してください","accepted":true},{"text":"チェックしてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"相談してください","start":29,"options":[{"text":"相談してください","accepted":true},{"text":"相談してみてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-069","text":"古い口座情報を削除しました。新しい登録内容も確認しました。","translation":"옛 계좌 정보를 삭제했습니다. 새 등록 내용도 확인했습니다.","sockets":[{"original":"削除しました","start":7,"options":[{"text":"削除しました","accepted":true},{"text":"消しました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"確認しました","start":22,"options":[{"text":"確認しました","accepted":true},{"text":"チェックしました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-070","text":"明細と領収書の金額に差があったので、担当者に確認しました。","translation":"명세와 영수증 금액에 차이가 있어서 담당자에게 확인했습니다.","sockets":[{"original":"差","start":10,"options":[{"text":"差","accepted":true},{"text":"違い","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"確認しました","start":22,"options":[{"text":"確認しました","accepted":true},{"text":"問い合わせました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-071","text":"設備の使い方を説明します。不明な点は質問してください。","translation":"설비 사용법을 설명합니다. 모르는 점은 질문해 주세요.","sockets":[{"original":"説明します","start":7,"options":[{"text":"説明します","accepted":true},{"text":"解説します","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"質問してください","start":18,"options":[{"text":"質問してください","accepted":true},{"text":"尋ねてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-072","text":"研修で操作の実演を行います。手順を確認しましょう。","translation":"연수에서 조작 시연을 실시합니다. 절차를 확인합시다.","sockets":[{"original":"行います","start":9,"options":[{"text":"行います","accepted":true},{"text":"実施します","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"確認しましょう","start":17,"options":[{"text":"確認しましょう","accepted":true},{"text":"チェックしましょう","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-073","text":"説明だけでは難しかったので、一緒に試してみました。その後で手順を確認しました。","translation":"설명만으로는 어려워서 함께 해 보았습니다. 그 뒤 절차를 확인했습니다.","sockets":[{"original":"試してみました","start":17,"options":[{"text":"試してみました","accepted":true},{"text":"やってみました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"確認しました","start":32,"options":[{"text":"確認しました","accepted":true},{"text":"チェックしました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-074","text":"原因を調べて、再発を防ぐ方法を考えます。","translation":"원인을 조사하고 재발을 막을 방법을 검토합니다.","sockets":[{"original":"調べて","start":3,"options":[{"text":"調べて","accepted":true},{"text":"調査して","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"考えます","start":15,"options":[{"text":"考えます","accepted":true},{"text":"検討します","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-075","text":"今回の結果を反省して、次の計画に改善点を取り入れます。","translation":"이번 결과를 반성하고 다음 계획에 개선점을 반영합니다.","sockets":[{"original":"反省して","start":6,"options":[{"text":"反省して","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"取り入れます","start":20,"options":[{"text":"取り入れます","accepted":true},{"text":"盛り込みます","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-076","text":"授業の資料をダウンロードして、事前に内容を確認してください。","translation":"수업 자료를 내려받고 미리 내용을 확인해 주세요.","sockets":[{"original":"ダウンロードして","start":6,"options":[{"text":"ダウンロードして","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"確認してください","start":21,"options":[{"text":"確認してください","accepted":true},{"text":"チェックしてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-077","text":"時間が短いので要点をまとめて説明してください。","translation":"시간이 짧으므로 요점을 정리해서 설명해 주세요.","sockets":[{"original":"まとめて","start":10,"options":[{"text":"まとめて","accepted":true},{"text":"整理して","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"説明してください","start":14,"options":[{"text":"説明してください","accepted":true},{"text":"解説してください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-078","text":"相手の話が終わるまで待って、最後まで聞いてください。","translation":"상대의 말이 끝날 때까지 기다리고 끝까지 들어 주세요.","sockets":[{"original":"待って","start":10,"options":[{"text":"待って","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"聞いてください","start":18,"options":[{"text":"聞いてください","accepted":true},{"text":"耳を傾けてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-079","text":"質問を整理しました。回答は後日メールで送ります。","translation":"질문을 정리했습니다. 답변은 추후 이메일로 보냅니다.","sockets":[{"original":"整理しました","start":3,"options":[{"text":"整理しました","accepted":true},{"text":"まとめました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"送ります","start":19,"options":[{"text":"送ります","accepted":true},{"text":"送付します","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-080","text":"研修の目的を理解してから課題に取り組んでください。提出前に見直してください。","translation":"연수 목적을 이해한 뒤 과제에 임해 주세요. 제출 전에 다시 확인해 주세요.","sockets":[{"original":"取り組んでください","start":15,"options":[{"text":"取り組んでください","accepted":true},{"text":"取り組みましょう","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"見直してください","start":29,"options":[{"text":"見直してください","accepted":true},{"text":"再確認してください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-081","text":"庭の草を刈りました。作業の後で道具を片付けました。","translation":"정원의 풀을 베었습니다. 작업 뒤에 도구를 정리했습니다.","sockets":[{"original":"刈りました","start":4,"options":[{"text":"刈りました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"片付けました","start":18,"options":[{"text":"片付けました","accepted":true},{"text":"整理しました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-082","text":"花を少し摘んで、受付の花瓶に飾りました。","translation":"꽃을 조금 따서 접수처 꽃병에 꽂았습니다.","sockets":[{"original":"摘んで","start":4,"options":[{"text":"摘んで","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"飾りました","start":14,"options":[{"text":"飾りました","accepted":true},{"text":"生けました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-083","text":"ほうきで玄関を掃いて、机の上も片付けました。","translation":"빗자루로 현관을 쓸고 책상 위도 정리했습니다.","sockets":[{"original":"掃いて","start":7,"options":[{"text":"掃いて","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"片付けました","start":15,"options":[{"text":"片付けました","accepted":true},{"text":"整理しました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-084","text":"窓から虹を眺めて、記念に写真を撮りました。","translation":"창문으로 무지개를 바라보고 기념으로 사진을 찍었습니다.","sockets":[{"original":"眺めて","start":5,"options":[{"text":"眺めて","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"撮りました","start":15,"options":[{"text":"撮りました","accepted":true},{"text":"撮影しました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-085","text":"缶詰を開ける前に賞味期限を確認してください。異常があれば使用をやめてください。","translation":"통조림을 열기 전에 품질 유지 기한을 확인해 주세요. 이상이 있으면 사용을 중단해 주세요.","sockets":[{"original":"確認してください","start":13,"options":[{"text":"確認してください","accepted":true},{"text":"チェックしてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"やめてください","start":31,"options":[{"text":"やめてください","accepted":true},{"text":"中止してください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-086","text":"かびが発生していたので、窓を開けて、管理会社に連絡しました。","translation":"곰팡이가 발생해서 창문을 열고 관리 회사에 알렸습니다.","sockets":[{"original":"開けて","start":14,"options":[{"text":"開けて","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"連絡しました","start":23,"options":[{"text":"連絡しました","accepted":true},{"text":"知らせました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-087","text":"お客様に温かいお茶を出しました。お客様は喜びました。","translation":"고객에게 따뜻한 차를 내드렸습니다. 고객은 기뻐했습니다.","sockets":[{"original":"出しました","start":10,"options":[{"text":"出しました","accepted":true},{"text":"お出ししました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"喜びました","start":20,"options":[{"text":"喜びました","accepted":true},{"text":"喜んでいました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-088","text":"通路のベッドを別の部屋に移して、通れることを確認しました。","translation":"통로의 침대를 다른 방으로 옮기고 통행할 수 있는지 확인했습니다.","sockets":[{"original":"移して","start":12,"options":[{"text":"移して","accepted":true},{"text":"移動して","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"確認しました","start":22,"options":[{"text":"確認しました","accepted":true},{"text":"チェックしました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-089","text":"卒業式の開始時刻を確認して、会場の地図も用意しました。","translation":"졸업식 시작 시각을 확인하고 행사장 지도도 준비했습니다.","sockets":[{"original":"確認して","start":9,"options":[{"text":"確認して","accepted":true},{"text":"チェックして","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"用意しました","start":20,"options":[{"text":"用意しました","accepted":true},{"text":"準備しました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-090","text":"親類の入院を聞いて病院に電話しました。面会時間を確認しました。","translation":"친척의 입원 소식을 듣고 병원에 전화했습니다. 면회 시간을 확인했습니다.","sockets":[{"original":"電話しました","start":12,"options":[{"text":"電話しました","accepted":true},{"text":"電話をかけました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"確認しました","start":24,"options":[{"text":"確認しました","accepted":true},{"text":"問い合わせました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-091","text":"個人情報は決められた場所に保管してください。外部への送信は控えてください。","translation":"개인정보는 정해진 곳에 보관해 주세요. 외부 전송은 삼가 주세요.","sockets":[{"original":"保管してください","start":13,"options":[{"text":"保管してください","accepted":true},{"text":"保存してください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"控えてください","start":29,"options":[{"text":"控えてください","accepted":true},{"text":"慎んでください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-092","text":"内容を誇張せず正確に伝えてください。数字の根拠も確認してください。","translation":"내용을 과장하지 말고 정확히 전달해 주세요. 수치의 근거도 확인해 주세요.","sockets":[{"original":"伝えてください","start":10,"options":[{"text":"伝えてください","accepted":true},{"text":"報告してください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"確認してください","start":24,"options":[{"text":"確認してください","accepted":true},{"text":"チェックしてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-093","text":"最新の情報を調べて、資料を更新します。","translation":"최신 정보를 확인하고 자료를 갱신합니다.","sockets":[{"original":"調べて","start":6,"options":[{"text":"調べて","accepted":true},{"text":"確認して","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"更新します","start":13,"options":[{"text":"更新します","accepted":true},{"text":"更新しておきます","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-094","text":"不規則な勤務で疲れているので上司に相談して、予定を調整します。","translation":"불규칙한 근무로 피곤해서 상사와 상담하고 일정을 조정합니다.","sockets":[{"original":"相談して","start":17,"options":[{"text":"相談して","accepted":true},{"text":"相談してみて","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"調整します","start":25,"options":[{"text":"調整します","accepted":true},{"text":"調整してみます","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-095","text":"単調な作業でも手順を守って、一つずつ進めましょう。","translation":"단조로운 작업도 절차를 지키며 하나씩 진행합시다.","sockets":[{"original":"守って","start":10,"options":[{"text":"守って","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"進めましょう","start":18,"options":[{"text":"進めましょう","accepted":true},{"text":"進めていきましょう","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-096","text":"利用者の意見を参考に構成を見直しました。変更点をまとめました。","translation":"이용자 의견을 참고해 구성을 재검토했습니다. 변경점을 정리했습니다.","sockets":[{"original":"見直しました","start":13,"options":[{"text":"見直しました","accepted":true},{"text":"再検討しました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"まとめました","start":24,"options":[{"text":"まとめました","accepted":true},{"text":"整理しました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-097","text":"第一印象だけで判断せず、仕事ぶりを見て、評価の理由を説明してください。","translation":"첫인상만으로 판단하지 말고 업무 태도를 보고 평가 이유를 설명해 주세요.","sockets":[{"original":"見て","start":17,"options":[{"text":"見て","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false},{"text":"ところが","accepted":false}]},{"original":"説明してください","start":26,"options":[{"text":"説明してください","accepted":true},{"text":"伝えてください","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-098","text":"関係者と話し合って、計画の難点を解決する方法を探します。","translation":"관계자와 협의하고 계획의 어려운 점을 해결할 방법을 찾습니다.","sockets":[{"original":"話し合って","start":4,"options":[{"text":"話し合って","accepted":true},{"text":"協議して","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"探します","start":23,"options":[{"text":"探します","accepted":true},{"text":"探っていきます","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-099","text":"説明書で分からなかったので担当者に尋ねて、操作方法を確認しました。","translation":"설명서로는 몰라서 담당자에게 물어 조작법을 확인했습니다.","sockets":[{"original":"尋ねて","start":17,"options":[{"text":"尋ねて","accepted":true},{"text":"聞いて","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"確認しました","start":26,"options":[{"text":"確認しました","accepted":true},{"text":"チェックしました","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]},{"id":"reading-v1-100","text":"協力してくれた皆さんに感謝します。結果は明日報告します。","translation":"협력해 주신 여러분께 감사드립니다. 결과는 내일 보고하겠습니다.","sockets":[{"original":"感謝します","start":11,"options":[{"text":"感謝します","accepted":true},{"text":"お礼を申し上げます","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]},{"original":"報告します","start":22,"options":[{"text":"報告します","accepted":true},{"text":"お知らせします","accepted":true},{"text":"しかしながら","accepted":false},{"text":"にもかかわらず","accepted":false}]}]}]$bank$::jsonb);
-- Import all parents before their children; generated UUIDs are resolved through natural keys.
insert into public.sentence(id,text_ja,translation_ko,status,batch)
select j->>'id',j->>'text',j->>'translation','published','sentence-bank-v1'
from sentence_import, jsonb_array_elements(data) j;
insert into public.sentence_socket(sentence_id,start_offset,end_offset,original_text)
select j->>'id',(k->>'start')::integer,(k->>'start')::integer+length(k->>'original'),k->>'original'
from sentence_import,jsonb_array_elements(data) j,jsonb_array_elements(j->'sockets') k;
insert into public.sentence_option(socket_id,word_id,display_text,reading,is_accepted)
select sk.id,w.id,o->>'text',case when w.term=o->>'text' then w.kana else null end,(o->>'accepted')::boolean
from sentence_import cross join lateral jsonb_array_elements(data) j cross join lateral jsonb_array_elements(j->'sockets') k cross join lateral jsonb_array_elements(k->'options') o
join public.sentence_socket sk on sk.sentence_id=j->>'id' and sk.start_offset=(k->>'start')::integer
left join public.word w on w.grammar_batch='sentence-pilot-100-v1' and w.deleted_at is null
 and w.term=case o->>'text'
 when '見積もって' then '見積もる' when '調達して' then '調達' when '反省して' then '反省'
 when '洗って' then '洗う' when '転びます' then '転ぶ' when '発車します' then '発車'
 when '刈りました' then '刈る' when '摘んで' then '摘む' when '喜びました' then '喜ぶ'
 when '製' then '～製' else o->>'text' end;
drop table public.reading_sentence;
